using Bdgrz.Compliance.Features.Criteria.Aggregates;
using Bdgrz.Compliance.Features.Criteria.Contracts;
using Bdgrz.Compliance.Features.Criteria.Events;
using Bdgrz.Compliance.Features.Criteria.Models;
using Bdgrz.Compliance.Features.Criteria.Rules;
using Bdgrz.Compliance.Features.Programs.Contracts;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.Criteria.Services;

/// <summary>Independently revalidates one committed value outcome through its actual source position.</summary>
internal sealed class CriteriaEditionValueDecisionEvidenceVerifier(ICriteriaExactSourceReader source,
    ICriteriaSourceCutCoverage coverage, ICriteriaPublicationAuthority publications, ICriteriaFreshEntryHead freshHead,
    ICriteriaParticipantCausalOrder? causalOrder = null)
{
    public async ValueTask<CriteriaEntryDecisionVerification> VerifyAsync(CriteriaOrderedSourceEvent proposalRecord,
        CriteriaOrderedSourceEvent decisionRecord, CancellationToken ct)
    {
        if (proposalRecord.Event is not CriteriaEditionValueProposed proposal || !CriteriaEditionValueRules.Shape(proposal.Intent) ||
            !CriteriaEditionValueRules.Admission(proposal.Intent, proposal.ExecutionGeneration, proposal.Actor, proposal.Admission))
            return CriteriaEntryDecisionVerification.Pending;
        var i = proposal.Intent;
        var owner = new CriteriaEditionValue(i.EditionId, i.TargetKind, i.Field, i.Category, i.Code);
        if (!Exact(proposalRecord, owner.Stream, owner.Id) || !Exact(decisionRecord, owner.Stream, owner.Id) ||
            proposalRecord.AreaOffset >= decisionRecord.AreaOffset || proposalRecord.ResourceOffset >= decisionRecord.ResourceOffset)
            return CriteriaEntryDecisionVerification.Pending;
        var (accepted, reason, evidence, editionId, operation, generation, proposalId) = decisionRecord.Event switch
        {
            CriteriaEditionValueAccepted value => (true, (string?)null, value.Evidence, value.EditionId,
                value.OperationId, value.ExecutionGeneration, value.ProposalEventId),
            CriteriaEditionValueRefused value => (false, (string?)value.Reason, value.Evidence, value.EditionId,
                value.OperationId, value.ExecutionGeneration, value.ProposalEventId),
            _ => (false, null, null, Uuid.Empty, Uuid.Empty, 0L, Uuid.Empty),
        };
        if (evidence is null || evidence.EditionEventId == Uuid.Empty || editionId != i.EditionId || operation != i.OperationId ||
            generation != proposal.ExecutionGeneration || proposalId != proposal.Metadata.EventId ||
            evidence.ProposalAreaOffset != proposalRecord.AreaOffset || evidence.EditionAreaOffset >= decisionRecord.AreaOffset ||
            evidence.EditionAreaOffset == proposalRecord.AreaOffset)
            return CriteriaEntryDecisionVerification.Pending;
        var actualProposal = await source.FindAsync(owner.Stream, owner.Id, proposal.Metadata.EventId, ct).ConfigureAwait(false);
        var actualDecision = await source.FindAsync(owner.Stream, owner.Id, decisionRecord.Event.Metadata.EventId, ct).ConfigureAwait(false);
        if (!Same(actualProposal, proposalRecord) || !Same(actualDecision, decisionRecord)) return CriteriaEntryDecisionVerification.Pending;

        var claimOwner = new CriteriaEditionValueOperation(i.EditionId, i.TargetKind, i.Field, i.Category, i.Code, i.OperationId);
        var claimRecord = await source.FindAsync(claimOwner.Stream, claimOwner.Id, proposal.OperationClaimEventId, ct).ConfigureAwait(false);
        if (claimRecord?.Event is not CriteriaEditionValueOperationClaimed claim || !Exact(claimRecord, claimOwner.Stream, claimOwner.Id) ||
            claim.Metadata.EventId != proposal.OperationClaimEventId || claim.Intent != i || claim.Actor != proposal.Actor ||
            claim.Admission is null || claim.Admission.UserId != proposal.Admission.UserId ||
            claim.ExecutionGeneration != proposal.ExecutionGeneration ||
            !CriteriaEditionValueRules.Admission(claim.Intent, claim.ExecutionGeneration, claim.Actor, claim.Admission))
            return CriteriaEntryDecisionVerification.Pending;

        var edition = new CriteriaEdition(i.EditionId);
        CriteriaOrderedSourceEvent? request = null, drafted = null, named = null, terminal = null;
        var lifecycle = new CriteriaEntryEditionLifecycle(i.EditionId, i.DraftGeneration);
        var participants = new CriteriaValueEditionParticipantVerifier(source, coverage, causalOrder);
        var namedActiveDraft = false;
        ulong next = 0;
        await foreach (var item in source.ReadAsync(edition.Stream, edition.Id, ct).ConfigureAwait(false))
        {
            if (!Exact(item, edition.Stream, edition.Id) || item.ResourceOffset != next++)
                throw new InvalidOperationException("The edition source is not a contiguous exact history.");
            if (!lifecycle.Apply(item.Event)) return CriteriaEntryDecisionVerification.Pending;
            if (!await participants.ObserveAsync(item, ct).ConfigureAwait(false)) return CriteriaEntryDecisionVerification.Pending;
            if (item.Event is CriteriaEditionDraftRequested r && r.Metadata.EventId == proposal.EditionRequestEventId &&
                r.EditionId == i.EditionId && r.DraftGeneration == i.DraftGeneration && r.OperationId == i.DraftGeneration &&
                r.Framework == "tsc" && r.SeedVersion is null && r.SeedFingerprint is null)
                request = item;
            if (item.Event is CriteriaEditionDrafted d && d.EditionId == i.EditionId && d.DraftGeneration == i.DraftGeneration && d.Framework == "tsc")
                drafted = item;
            if (item.Event.Metadata.EventId == evidence.EditionEventId)
            {
                named = item;
                namedActiveDraft = lifecycle.ValueActive;
            }
            if (item.AreaOffset >= decisionRecord.AreaOffset) continue;
            if (item.Event is CriteriaEditionPublished published && published.EditionId == i.EditionId && published.DraftGeneration == i.DraftGeneration ||
                item.Event is CriteriaEditionDraftAbandoned abandoned && abandoned.EditionId == i.EditionId && abandoned.DraftGeneration == i.DraftGeneration)
            {
                if (terminal is not null) throw new InvalidOperationException("The edition has multiple terminal facts.");
                terminal = item;
            }
        }
        if (request is null || drafted is null || named is null ||
            !(request.AreaOffset < drafted.AreaOffset && drafted.AreaOffset < claimRecord.AreaOffset &&
              claimRecord.AreaOffset < proposalRecord.AreaOffset) ||
            named.ResourceOffset != evidence.EditionResourceOffset || named.AreaOffset != evidence.EditionAreaOffset ||
            named.ResourceOffset < drafted.ResourceOffset ||
            !await new CriteriaEditionValueDecisionAuthority(source, coverage, publications, freshHead, causalOrder)
                .VerifyDraftBindingAsync(request, drafted, ct).ConfigureAwait(false) ||
            !await coverage.CoversAsync(edition.Stream, next, decisionRecord.AreaOffset, ct).ConfigureAwait(false))
            return CriteriaEntryDecisionVerification.Pending;

        switch (evidence.Basis)
        {
            case "draft" when accepted && reason is null:
                if (!namedActiveDraft) return CriteriaEntryDecisionVerification.Pending;
                if (terminal is null) return CriteriaEntryDecisionVerification.Verified;
                if (named.AreaOffset >= terminal.AreaOffset || proposalRecord.AreaOffset >= terminal.AreaOffset)
                    return CriteriaEntryDecisionVerification.Pending;
                if (terminal.Event is CriteriaEditionDraftAbandoned abandoned)
                    return CriteriaEntryDecisionSourceRules.ValidAbandonment(abandoned)
                        ? CriteriaEntryDecisionVerification.Abandoned : CriteriaEntryDecisionVerification.Pending;
                return await PublishedAsync(i.EditionId, terminal, ct).ConfigureAwait(false)
                    ? CriteriaEntryDecisionVerification.Verified : CriteriaEntryDecisionVerification.Pending;
            case "publication" when terminal?.Event is CriteriaEditionPublished && terminal.Event.Metadata.EventId == evidence.EditionEventId:
                if (!(accepted && reason is null && proposalRecord.AreaOffset < terminal.AreaOffset ||
                      !accepted && reason == "edition_published" && proposalRecord.AreaOffset > terminal.AreaOffset))
                    return CriteriaEntryDecisionVerification.Pending;
                return await PublishedAsync(i.EditionId, terminal, ct).ConfigureAwait(false)
                    ? CriteriaEntryDecisionVerification.Verified : CriteriaEntryDecisionVerification.Pending;
            case "abandonment" when !accepted && reason == "edition_abandoned" &&
                terminal?.Event is CriteriaEditionDraftAbandoned abandoned && CriteriaEntryDecisionSourceRules.ValidAbandonment(abandoned) &&
                terminal.Event.Metadata.EventId == evidence.EditionEventId:
                return CriteriaEntryDecisionVerification.Abandoned;
            default:
                return CriteriaEntryDecisionVerification.Pending;
        }
    }

    async ValueTask<bool> PublishedAsync(Uuid editionId, CriteriaOrderedSourceEvent terminal, CancellationToken ct)
    {
        var proof = await publications.ReadPublishedAsync(editionId, ct).ConfigureAwait(false);
        return proof.IsSuccess && proof.Value is { } published && published.EditionId == editionId &&
            published.EventId == terminal.Event.Metadata.EventId && published.ResourceOffset == terminal.ResourceOffset;
    }

    static bool Exact(CriteriaOrderedSourceEvent item, EventStreamAddress stream, Uuid id) =>
        item.Stream == stream && item.Event.Metadata.AggregateId == id && !item.Event.Metadata.IsAudit &&
        item.Event.Metadata.EventId != Uuid.Empty && item.Event.Metadata.AggregateVersion == checked(item.ResourceOffset + 1);

    static bool Same(CriteriaOrderedSourceEvent? actual, CriteriaOrderedSourceEvent expected) =>
        actual is not null && actual.Stream == expected.Stream && actual.ResourceOffset == expected.ResourceOffset &&
        actual.AreaOffset == expected.AreaOffset && actual.Event == expected.Event &&
        actual.Event.Metadata.EventId == expected.Event.Metadata.EventId &&
        actual.Event.Metadata.AggregateId == expected.Event.Metadata.AggregateId &&
        actual.Event.Metadata.AggregateVersion == expected.Event.Metadata.AggregateVersion && !actual.Event.Metadata.IsAudit;
}

state.CriteriaEntryEditionLifecycle.cs:
using Bdgrz.Compliance.Features.AccessControl.Models;
using Bdgrz.Compliance.Features.AccessControl.Services;
using Bdgrz.Compliance.Features.Criteria.Aggregates;
using Bdgrz.Compliance.Features.Criteria.Commands;
using Bdgrz.Compliance.Features.Criteria.Events;
using Bdgrz.Compliance.Features.Criteria.Rules;
using Bdgrz.Compliance.Features.Kernel.Services;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.Criteria.Services;

/// <summary>Bounded edition lifecycle fold for entry decisions, not a child roster.</summary>
/// <remarks>Entry edits may continue through rename, publication attempts and abort cleanup.</remarks>
internal sealed class CriteriaEntryEditionLifecycle(Uuid editionId, Uuid draftGeneration)
{
    string _status = "empty";
    Uuid _pending;
    Uuid _attempt;
    long _ordinal;
    string? _label;
    string? _requestedLabel;
    long _labelGeneration;
    Uuid _labelConfirmation;
    string? _witness;
    Uuid _witnessIncarnation;
    ActorAttribution? _publicationActor;
    string? _seedVersion;
    string? _seedFingerprint;
    long _executionFloor = 1;

    public bool Active => _status is "draft" or "renaming" or "confirming" or "publishing" or "abort_cleanup";
    public bool ValueActive => _status == "draft";

    public bool Apply(DomainEvent value)
    {
        switch (value)
        {
            case CriteriaEditionOperationAttemptFenced fence when fence.EditionId == editionId && fence.OperationId != Uuid.Empty &&
                fence.ExecutionGeneration >= _executionFloor && fence.IntentSha256 is { Length: 64 } &&
                fence.IntentSha256.All(static value => value is >= '0' and <= '9' or >= 'a' and <= 'f') &&
                fence.Metadata.AggregateVersion > 0 && fence.ExpectedPosition == fence.Metadata.AggregateVersion - 1:
                _executionFloor = checked(fence.ExecutionGeneration + 1); return true;
            case CriteriaEditionDraftRequested request when _status == "empty" && request.EditionId == editionId &&
                request.DraftGeneration == draftGeneration && request.OperationId == draftGeneration &&
                request.Framework == "tsc" && EditionLabelClaim.TryNormalize(request.Label, out var initialLabel) &&
                initialLabel == request.Label && ValidDraftRequest(request):
                _pending = request.OperationId; _requestedLabel = request.Label; _seedVersion = request.SeedVersion;
                _seedFingerprint = request.SeedFingerprint; _status = "pending"; return true;
            case CriteriaInitialLabelRefused initialRefusal when _status == "pending" && initialRefusal.EditionId == editionId &&
                initialRefusal.OperationId == _pending && initialRefusal.Label == _requestedLabel &&
                initialRefusal.RefusalEventId != Uuid.Empty:
                _status = "needs_label"; return true;
            case CriteriaInitialLabelRequested requested when _status == "needs_label" && requested.EditionId == editionId &&
                requested.OperationId != Uuid.Empty && EditionLabelClaim.TryNormalize(requested.Label, out var requestedLabel) &&
                requestedLabel == requested.Label && ValidHuman(requested.OperationId, requested.ExecutionGeneration,
                    requested.Actor, requested.Admission, new ChooseInitialEditionLabel(editionId, requested.OperationId, requested.Label)):
                _pending = requested.OperationId; _requestedLabel = requested.Label; _status = "pending"; return true;
            case CriteriaEditionDraftActivated activated when _status == "pending" && activated.EditionId == editionId &&
                activated.DraftGeneration == draftGeneration && activated.OperationId == _pending && activated.Framework == "tsc" &&
                activated.Label == _requestedLabel && activated.LabelGeneration > 0 && activated.ReservationEventId != Uuid.Empty:
                _label = activated.Label; _labelGeneration = activated.LabelGeneration; _status = "activating"; return true;
            case CriteriaEditionDrafted drafted when _status == "activating" && drafted.EditionId == editionId &&
                drafted.DraftGeneration == draftGeneration && drafted.OperationId == _pending && drafted.Framework == "tsc" &&
                drafted.Label == _label && drafted.LabelGeneration == _labelGeneration && drafted.ConfirmationEventId != Uuid.Empty:
                _labelConfirmation = drafted.ConfirmationEventId; _pending = Uuid.Empty; _requestedLabel = null; _status = "draft"; return true;
            case CriteriaEditionDraftRequestCancelled draftCancelled when (_status is "pending" or "needs_label" or "activating") &&
                draftCancelled.EditionId == editionId && draftCancelled.TargetOperationId == _pending &&
                draftCancelled.OperationId != draftCancelled.TargetOperationId &&
                ValidHuman(draftCancelled.OperationId, draftCancelled.ExecutionGeneration, draftCancelled.Actor, draftCancelled.Admission,
                    new CancelCriteriaEditionDraftRequest(editionId, draftCancelled.OperationId, draftCancelled.TargetOperationId)):
                _status = "abandoned"; return true;
            case CriteriaEditionRenameRequested rename when _status == "draft" && rename.EditionId == editionId &&
                rename.OperationId != Uuid.Empty && rename.OldLabel == _label && rename.OldLabelGeneration == _labelGeneration &&
                EditionLabelClaim.TryNormalize(rename.NewLabel, out var nextLabel) && nextLabel == rename.NewLabel && rename.NewLabel != _label &&
                ValidHuman(rename.OperationId, rename.ExecutionGeneration, rename.Actor, rename.Admission,
                    new BeginCriteriaEditionRename(editionId, rename.OperationId, rename.NewLabel)):
                _pending = rename.OperationId; _requestedLabel = rename.NewLabel; _status = "renaming"; return true;
            case CriteriaEditionDraftRenamed renamed when _status == "renaming" && renamed.EditionId == editionId &&
                renamed.OperationId == _pending && renamed.OldLabel == _label && renamed.OldLabelGeneration == _labelGeneration &&
                renamed.NewLabel == _requestedLabel && renamed.NewLabelGeneration > 0 && renamed.ReservationEventId != Uuid.Empty:
                _label = renamed.NewLabel; _labelGeneration = renamed.NewLabelGeneration; _status = "confirming"; return true;
            case CriteriaEditionRenameCompleted completed when _status == "confirming" && completed.EditionId == editionId &&
                completed.OperationId == _pending && completed.Label == _label && completed.LabelGeneration == _labelGeneration &&
                completed.ConfirmationEventId != Uuid.Empty:
                _labelConfirmation = completed.ConfirmationEventId; _pending = Uuid.Empty; _requestedLabel = null; _status = "draft"; return true;
            case CriteriaEditionRenameRefused renameRefusal when _status == "renaming" && renameRefusal.EditionId == editionId &&
                renameRefusal.OperationId == _pending:
                _pending = Uuid.Empty; _status = "draft"; return true;
            case CriteriaEditionRenameCancelled renameCancelled when _status == "renaming" && renameCancelled.EditionId == editionId &&
                renameCancelled.RenameOperationId == _pending && renameCancelled.OperationId != renameCancelled.RenameOperationId &&
                ValidHuman(renameCancelled.OperationId, renameCancelled.ExecutionGeneration, renameCancelled.Actor, renameCancelled.Admission,
                    new CancelCriteriaEditionRename(editionId, renameCancelled.OperationId, renameCancelled.RenameOperationId)):
                _pending = Uuid.Empty; _status = "draft"; return true;
            case CriteriaPublicationStarted started when _status == "draft" && started.EditionId == editionId &&
                started.DraftGeneration == draftGeneration && started.PublicationAttemptId != Uuid.Empty &&
                started.AttemptOrdinal == checked(_ordinal + 1) && !string.IsNullOrWhiteSpace(started.WitnessIdentifier) &&
                started.WitnessIncarnationId != Uuid.Empty && started.Label == _label && started.LabelGeneration == _labelGeneration &&
                started.LabelConfirmationEventId == _labelConfirmation && _labelConfirmation != Uuid.Empty && ValidPublicationStart(started):
                _attempt = started.PublicationAttemptId; _ordinal = started.AttemptOrdinal; _witness = started.WitnessIdentifier;
                _witnessIncarnation = started.WitnessIncarnationId; _publicationActor = started.Actor; _status = "publishing"; return true;
            case CriteriaPublicationAborted aborted when _status == "publishing" && aborted.EditionId == editionId &&
                aborted.DraftGeneration == draftGeneration && aborted.PublicationAttemptId == _attempt && aborted.AttemptOrdinal == _ordinal &&
                aborted.WitnessIdentifier == _witness && aborted.WitnessIncarnationId == _witnessIncarnation:
                _status = "abort_cleanup"; return true;
            case CriteriaPublicationAbortCleanupCompleted cleanup when _status == "abort_cleanup" && cleanup.EditionId == editionId &&
                cleanup.DraftGeneration == draftGeneration && cleanup.PublicationAttemptId == _attempt && cleanup.AttemptOrdinal == _ordinal &&
                cleanup.WitnessIdentifier == _witness && cleanup.WitnessIncarnationId == _witnessIncarnation && cleanup.WitnessFenceEventId != Uuid.Empty:
                _attempt = Uuid.Empty; _status = "draft"; return true;
            case CriteriaEditionPublished published when _status == "publishing" && published.EditionId == editionId &&
                published.DraftGeneration == draftGeneration && published.PublicationAttemptId == _attempt && published.AttemptOrdinal == _ordinal &&
                published.WitnessIdentifier == _witness && published.WitnessIncarnationId == _witnessIncarnation && published.Label == _label &&
                published.LabelGeneration == _labelGeneration && published.LabelConfirmationEventId == _labelConfirmation &&
                published.WitnessPinEventId != Uuid.Empty && published.PublishedBy == _publicationActor:
                _status = "published"; return true;
            case CriteriaEditionDraftAbandoned abandoned when _status == "draft" && abandoned.EditionId == editionId &&
                abandoned.DraftGeneration == draftGeneration && abandoned.Label == _label && abandoned.LabelGeneration == _labelGeneration &&
                abandoned.ExecutionGeneration >= _executionFloor && CriteriaEntryDecisionSourceRules.ValidAbandonment(abandoned):
                _status = "abandoned"; return true;
            default:
                return false;
        }
    }

    bool ValidDraftRequest(CriteriaEditionDraftRequested request)
    {
        if (request.OperationId == Uuid.Empty || request.ExecutionGeneration < _executionFloor)
            return false;
        if (request.Admission is null)
        {
            var seed = PlatformCriteriaCatalog.SeedEdition();
            return request.Actor == new ActorAttribution("criteria-seed-bootstrap", "system") &&
                   request.EditionId == seed.EditionId && request.Label == seed.EditionLabel &&
                   request.OperationId == PlatformCriteriaSeedDefinition.OperationOf(seed.EditionId, "edition") &&
                   PlatformCriteriaSeedDefinition.MatchesBinding(request.EditionId, request.SeedVersion, request.SeedFingerprint);
        }
        return request.SeedVersion is null && request.SeedFingerprint is null &&
               ValidHuman(request.OperationId, request.ExecutionGeneration, request.Actor, request.Admission,
                   new DraftCriteriaEdition(editionId, request.OperationId, request.Framework, request.Label));
    }

    bool ValidPublicationStart(CriteriaPublicationStarted started)
    {
        if (started.ExecutionGeneration < _executionFloor)
            return false;
        return started.Admission is null
            ? started.Actor == new ActorAttribution("criteria-seed-bootstrap", "system") &&
              PlatformCriteriaSeedDefinition.MatchesBinding(editionId, _seedVersion, _seedFingerprint)
            : ValidHuman(started.PublicationAttemptId, started.ExecutionGeneration, started.Actor, started.Admission,
                new BeginCriteriaPublication(editionId, started.PublicationAttemptId,
                    started.WitnessIdentifier, started.WitnessIncarnationId));
    }

    bool ValidHuman(Uuid operation, long generation, ActorAttribution actor, AccessAdmissionEvidence? admission, object request)
    {
        if (operation == Uuid.Empty || generation < _executionFloor || admission is null ||
            !CriteriaContentBounds.AdmissionFields(actor, admission))
            return false;
        var digest = request switch
        {
            DraftCriteriaEdition value => AuthoredIntentDigest.Compute(value),
            ChooseInitialEditionLabel value => AuthoredIntentDigest.Compute(value),
            CancelCriteriaEditionDraftRequest value => AuthoredIntentDigest.Compute(value),
            BeginCriteriaEditionRename value => AuthoredIntentDigest.Compute(value),
            CancelCriteriaEditionRename value => AuthoredIntentDigest.Compute(value),
            BeginCriteriaPublication value => AuthoredIntentDigest.Compute(value),
            _ => throw new InvalidOperationException("Unsupported edition lifecycle intent."),
        };
        return AccessAdmissionEvidenceBinding.BindsCriteriaOperator(admission, admission.UserId, actor, operation,
            new CriteriaEdition(editionId).Stream.ToString(), CriteriaEdition.BindAdmissionDigest(digest, generation));
    }
}

using Bdgrz.Compliance.Features.Criteria.Aggregates;
using Bdgrz.Compliance.Features.Criteria.Events;
using Bdgrz.Compliance.Features.Criteria.Handlers;
using Bdgrz.Compliance.Features.Criteria.Rules;
using Bdgrz.Compliance.Features.Criteria.Contracts;
using Cntryl.Portia;

namespace Bdgrz.Compliance.Features.Criteria.Services;

/// <summary>Checks independently owned label and witness outcomes in one edition history.</summary>
/// <remarks>A missing or unqualified participant fact is pending, never evidence of success.</remarks>
internal sealed class CriteriaValueEditionParticipantVerifier(ICriteriaExactSourceReader source,
    ICriteriaSourceCutCoverage coverage, ICriteriaParticipantCausalOrder? causalOrder = null)
{
    CriteriaOrderedSourceEvent? _initialRequest;
    CriteriaOrderedSourceEvent? _renameRequest;
    CriteriaOrderedSourceEvent? _renamed;
    CriteriaOrderedSourceEvent? _aborted;

    public async ValueTask<bool> ObserveAsync(CriteriaOrderedSourceEvent record, CancellationToken ct)
    {
        switch (record.Event)
        {
            case CriteriaEditionDraftRequested or CriteriaInitialLabelRequested:
                _initialRequest = record;
                return true;
            case CriteriaInitialLabelRefused refused:
                return _initialRequest is not null && refused.Reason == ApplyCriteriaEditionLabelRefusalHandler.Reason &&
                    await VerifyRefusalAsync(_initialRequest, refused.EditionId, refused.OperationId,
                        refused.Label, refused.RefusalEventId, record, ct).ConfigureAwait(false);
            case CriteriaEditionRenameRequested:
                _renameRequest = record;
                _renamed = null;
                return true;
            case CriteriaEditionDraftRenamed renamed:
                if (_renameRequest?.Event is not CriteriaEditionRenameRequested request ||
                    _renameRequest.AreaOffset >= record.AreaOffset || request.EditionId != renamed.EditionId ||
                    request.OperationId != renamed.OperationId || request.NewLabel != renamed.NewLabel ||
                    request.OldLabel != renamed.OldLabel || request.OldLabelGeneration != renamed.OldLabelGeneration)
                    return false;
                var reservation = await FindReservationAsync(request, renamed.ReservationEventId, ct).ConfigureAwait(false);
                if (reservation is null || reservation.Event is not EditionLabelReserved held || held.Generation != renamed.NewLabelGeneration ||
                    !await PrecedesAsync(_renameRequest!, reservation, ct).ConfigureAwait(false) ||
                    !await PrecedesAsync(reservation, record, ct).ConfigureAwait(false))
                    return false;
                _renamed = record;
                return true;
            case CriteriaEditionRenameCompleted completed:
                if (_renameRequest?.Event is not CriteriaEditionRenameRequested intent ||
                    _renamed?.Event is not CriteriaEditionDraftRenamed committed || _renamed.AreaOffset >= record.AreaOffset ||
                    completed.EditionId != intent.EditionId || completed.OperationId != intent.OperationId ||
                    completed.Label != intent.NewLabel || completed.LabelGeneration != committed.NewLabelGeneration)
                    return false;
                var reserved = await FindReservationAsync(intent, committed.ReservationEventId, ct).ConfigureAwait(false);
                if (reserved is null) return false;
                var claim = new EditionLabelClaim(completed.Label);
                var confirmation = await source.FindAsync(claim.Stream, claim.Id, completed.ConfirmationEventId, ct).ConfigureAwait(false);
                if (confirmation?.Event is not EditionLabelConfirmed confirmed || !Exact(confirmation, claim.Stream, claim.Id) ||
                    confirmed.Metadata.EventId != completed.ConfirmationEventId ||
                    confirmation.ResourceOffset <= reserved.ResourceOffset || confirmed.EditionId != completed.EditionId ||
                    confirmed.OperationId != completed.OperationId || confirmed.Label != completed.Label ||
                    confirmed.Generation != completed.LabelGeneration || confirmed.EditionAcceptedEventId != committed.Metadata.EventId ||
                    !await VerifyConfirmationHistoryAsync(claim, reserved, confirmation, ct).ConfigureAwait(false) ||
                    !await PrecedesAsync(_renamed!, confirmation, ct).ConfigureAwait(false) ||
                    !await PrecedesAsync(confirmation, record, ct).ConfigureAwait(false))
                    return false;
                _renameRequest = _renamed = null;
                return true;
            case CriteriaEditionRenameRefused renameRefusal:
                if (_renameRequest?.Event is not CriteriaEditionRenameRequested failed ||
                    renameRefusal.Reason != ApplyCriteriaEditionLabelRefusalHandler.Reason ||
                    !await VerifyRefusalAsync(_renameRequest, renameRefusal.EditionId, renameRefusal.OperationId,
                        failed.NewLabel, renameRefusal.RefusalEventId, record, ct).ConfigureAwait(false)) return false;
                _renameRequest = _renamed = null;
                return true;
            case CriteriaEditionRenameCancelled:
                _renameRequest = _renamed = null;
                return true;
            case CriteriaPublicationAborted:
                _aborted = record;
                return true;
            case CriteriaPublicationAbortCleanupCompleted cleanup:
                if (_aborted?.Event is not CriteriaPublicationAborted aborted || _aborted.AreaOffset >= record.AreaOffset ||
                    aborted.EditionId != cleanup.EditionId || aborted.DraftGeneration != cleanup.DraftGeneration ||
                    aborted.PublicationAttemptId != cleanup.PublicationAttemptId || aborted.AttemptOrdinal != cleanup.AttemptOrdinal ||
                    aborted.WitnessIdentifier != cleanup.WitnessIdentifier || aborted.WitnessIncarnationId != cleanup.WitnessIncarnationId)
                    return false;
                if (!CriteriaContentBounds.Identifier(cleanup.WitnessIdentifier)) return false;
                var witness = new CriteriaEntry(cleanup.EditionId, cleanup.WitnessIdentifier);
                var fence = await source.FindAsync(witness.Stream, witness.Id, cleanup.WitnessFenceEventId, ct).ConfigureAwait(false);
                if (fence?.Event is not CriterionWitnessPinFenced pinned || !Exact(fence, witness.Stream, witness.Id) ||
                    pinned.Metadata.EventId != cleanup.WitnessFenceEventId ||
                    _aborted.AreaOffset >= fence.AreaOffset || fence.AreaOffset >= record.AreaOffset ||
                    pinned.EditionId != cleanup.EditionId || pinned.DraftGeneration != cleanup.DraftGeneration ||
                    pinned.Identifier != cleanup.WitnessIdentifier || pinned.PublicationAttemptId != cleanup.PublicationAttemptId ||
                    pinned.AttemptOrdinal != cleanup.AttemptOrdinal || pinned.IncarnationId != cleanup.WitnessIncarnationId ||
                    pinned.PublicationAbortedEventId != aborted.Metadata.EventId)
                    return false;
                _aborted = null;
                return true;
            default:
                return true;
        }
    }

    async ValueTask<CriteriaOrderedSourceEvent?> FindReservationAsync(CriteriaEditionRenameRequested request,
        Uuid reservationId, CancellationToken ct)
    {
        if (reservationId == Uuid.Empty) return null;
        var owner = new EditionLabelClaim(request.NewLabel);
        var found = await source.FindAsync(owner.Stream, owner.Id, reservationId, ct).ConfigureAwait(false);
        return found?.Event is EditionLabelReserved reserved && Exact(found, owner.Stream, owner.Id) &&
            reserved.Metadata.EventId == reservationId &&
            reserved.Label == request.NewLabel && reserved.EditionId == request.EditionId &&
            reserved.OperationId == request.OperationId && reserved.EditionRequestEventId == request.Metadata.EventId &&
            reserved.RequestedBy == request.Actor && reserved.Generation > 0 ? found : null;
    }

    async ValueTask<bool> VerifyRefusalAsync(CriteriaOrderedSourceEvent request, Uuid editionId, Uuid operationId,
        string label, Uuid refusalId, CriteriaOrderedSourceEvent outcome, CancellationToken ct)
    {
        if (refusalId == Uuid.Empty || !EditionLabelClaim.TryNormalize(label, out var normalized) || normalized != label)
            return false;
        var claim = new EditionLabelClaim(label);
        EditionLabelReserved? holder = null;
        long generation = 0;
        ulong next = 0;
        await foreach (var item in source.ReadAsync(claim.Stream, claim.Id, ct).ConfigureAwait(false))
        {
            if (!Exact(item, claim.Stream, claim.Id) || item.ResourceOffset != next++)
                throw new InvalidOperationException("The label participant source is not contiguous.");
            if (item.Event.Metadata.EventId == refusalId)
            {
                if (item.Event is not EditionLabelReservationRefused refused || holder is null ||
                    refused.Label != label || refused.EditionId != editionId || refused.OperationId != operationId ||
                    refused.EditionRequestEventId != request.Event.Metadata.EventId ||
                    refused.RequestedBy != RequestActorOf(request.Event) || generation == long.MaxValue ||
                    refused.RequestedGeneration != generation + 1 || refused.HolderEditionId != holder.EditionId ||
                    refused.HolderOperationId != holder.OperationId || refused.HolderGeneration != holder.Generation ||
                    refused.HolderReservationEventId != holder.Metadata.EventId ||
                    (holder.EditionId == editionId && holder.OperationId == operationId)) return false;
                return await coverage.CoversAsync(claim.Stream, next, item.AreaOffset, ct).ConfigureAwait(false) &&
                    await PrecedesAsync(request, item, ct).ConfigureAwait(false) &&
                    await PrecedesAsync(item, outcome, ct).ConfigureAwait(false);
            }
            switch (item.Event)
            {
                case EditionLabelReserved reserved:
                    if (holder is not null || generation == long.MaxValue || reserved.Label != label ||
                        reserved.Generation != generation + 1 || reserved.Metadata.EventId == Uuid.Empty ||
                        reserved.EditionId == Uuid.Empty || reserved.OperationId == Uuid.Empty || reserved.EditionRequestEventId == Uuid.Empty ||
                        reserved.EditionId == editionId && reserved.OperationId == operationId) return false;
                    holder = reserved; generation = reserved.Generation; break;
                case EditionLabelReleased released:
                    if (holder is null || released.Label != label || released.EditionId != holder.EditionId ||
                        released.OperationId != holder.OperationId || released.Generation != holder.Generation) return false;
                    holder = null; break;
                case EditionLabelConfirmed confirmed:
                    if (holder is null || confirmed.Label != label || confirmed.EditionId != holder.EditionId ||
                        confirmed.OperationId != holder.OperationId || confirmed.Generation != holder.Generation ||
                        confirmed.EditionAcceptedEventId == Uuid.Empty) return false;
                    break;
                case EditionLabelReservationRefused earlier when earlier.EditionId == editionId && earlier.OperationId == operationId:
                case EditionLabelReservationFenced fenced when fenced.EditionId == editionId && fenced.OperationId == operationId:
                    return false;
            }
        }
        return false;
    }

    internal async ValueTask<bool> VerifyConfirmationHistoryAsync(EditionLabelClaim owner, CriteriaOrderedSourceEvent reservation,
        CriteriaOrderedSourceEvent confirmation, CancellationToken ct)
    {
        if (reservation.Event is not EditionLabelReserved expected || confirmation.Event is not EditionLabelConfirmed expectedConfirmation)
            return false;
        EditionLabelReserved? holder = null;
        long generation = 0;
        ulong next = 0;
        await foreach (var item in source.ReadAsync(owner.Stream, owner.Id, ct).ConfigureAwait(false))
        {
            if (!Exact(item, owner.Stream, owner.Id) || item.ResourceOffset != next++)
                throw new InvalidOperationException("The label participant source is not contiguous.");
            if (item.Event.Metadata.EventId == expectedConfirmation.Metadata.EventId)
            {
                if (item.ResourceOffset != confirmation.ResourceOffset || item.Event != expectedConfirmation ||
                    holder is null || holder.Metadata.EventId != expected.Metadata.EventId) return false;
                return await coverage.CoversAsync(owner.Stream, next, item.AreaOffset, ct).ConfigureAwait(false);
            }
            switch (item.Event)
            {
                case EditionLabelReserved held:
                    if (holder is not null || generation == long.MaxValue || held.Label != owner.Label ||
                        held.Generation != generation + 1 || held.EditionId == Uuid.Empty || held.OperationId == Uuid.Empty ||
                        held.EditionRequestEventId == Uuid.Empty) return false;
                    if (held.Metadata.EventId == expected.Metadata.EventId &&
                        (item.ResourceOffset != reservation.ResourceOffset || held != expected)) return false;
                    holder = held; generation = held.Generation; break;
                case EditionLabelReleased released:
                    if (holder is null || released.Label != owner.Label || released.EditionId != holder.EditionId ||
                        released.OperationId != holder.OperationId || released.Generation != holder.Generation) return false;
                    holder = null; break;
                case EditionLabelConfirmed confirmed:
                    if (holder is null || confirmed.Label != owner.Label || confirmed.EditionId != holder.EditionId ||
                        confirmed.OperationId != holder.OperationId || confirmed.Generation != holder.Generation ||
                        confirmed.EditionAcceptedEventId == Uuid.Empty ||
                        confirmed.EditionId == expected.EditionId && confirmed.OperationId == expected.OperationId) return false;
                    break;
                case EditionLabelReservationRefused prior when prior.EditionId == expected.EditionId && prior.OperationId == expected.OperationId:
                case EditionLabelReservationFenced priorFence when priorFence.EditionId == expected.EditionId && priorFence.OperationId == expected.OperationId:
                    return false;
            }
        }
        return false;
    }

    static ActorAttribution? RequestActorOf(DomainEvent value) => value switch
    {
        CriteriaEditionDraftRequested e => e.Actor,
        CriteriaInitialLabelRequested e => e.Actor,
        CriteriaEditionRenameRequested e => e.Actor,
        _ => null,
    };

    ValueTask<bool> PrecedesAsync(CriteriaOrderedSourceEvent first, CriteriaOrderedSourceEvent second, CancellationToken ct) =>
        causalOrder is null ? ValueTask.FromResult(false) : causalOrder.PrecedesAsync(first, second, ct);

    static bool Exact(CriteriaOrderedSourceEvent item, EventStreamAddress stream, Uuid id) =>
        item.Stream == stream && item.Event.Metadata.AggregateId == id && !item.Event.Metadata.IsAudit &&
        item.Event.Metadata.EventId != Uuid.Empty && item.Event.Metadata.AggregateVersion == checked(item.ResourceOffset + 1);
}

